import{_ as t,o,c as r,ae as a}from"./chunks/framework.BvHJbMD4.js";const d=JSON.parse('{"title":"The Cast: The Best for the Mystery","description":"","frontmatter":{},"headers":[],"relativePath":"en/cast.md","filePath":"en/cast.md"}'),s={name:"en/cast.md"};function i(n,e,h,l,u,c){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="the-cast-the-best-for-the-mystery" tabindex="-1">The Cast: The Best for the Mystery <a class="header-anchor" href="#the-cast-the-best-for-the-mystery" aria-label="Permalink to &quot;The Cast: The Best for the Mystery&quot;">​</a></h1><p>For our mockumentary, we&#39;ve secured some of the most prominent faces in German-language cinema. They don&#39;t just play their roles; they inhabit the absurdity of their characters.</p><h2 id="birgit-minichmayr-as-heidi-goess-horten" tabindex="-1">Birgit Minichmayr as Heidi Goëss-Horten <a class="header-anchor" href="#birgit-minichmayr-as-heidi-goess-horten" aria-label="Permalink to &quot;Birgit Minichmayr as Heidi Goëss-Horten&quot;">​</a></h2><p><strong>The Role:</strong> The Grande Dame of Lake Wörthersee. <strong>The Performance:</strong> Minichmayr plays Heidi with a mix of razor-sharp irony and disarming friendliness. She manages to present the &quot;donation splitting&quot; as an act of pure artistic benevolence. Her Heidi is both a victim of her own luxury and the director of a political system.</p><h2 id="august-diehl-as-helmut-horten-the-young-helmut" tabindex="-1">August Diehl as Helmut Horten (The Young Helmut) <a class="header-anchor" href="#august-diehl-as-helmut-horten-the-young-helmut" aria-label="Permalink to &quot;August Diehl as Helmut Horten (The Young Helmut)&quot;">​</a></h2><p><strong>The Role:</strong> The Department Store King and &quot;Market Optimizer.&quot; <strong>The Performance:</strong> Diehl brings his famous undercooled intensity. His Helmut is not an ideologue, but a &quot;manager of opportunities.&quot; In the 1930s scenes, he shows with terrifying calm how he &quot;acquires&quot; stores while the world around him collapses. He is the master of the &quot;pointillism of capital.&quot;</p><h2 id="oliver-masucci-as-the-multi-role-chronist" tabindex="-1">Oliver Masucci as the Multi-Role / Chronist <a class="header-anchor" href="#oliver-masucci-as-the-multi-role-chronist" aria-label="Permalink to &quot;Oliver Masucci as the Multi-Role / Chronist&quot;">​</a></h2><p><strong>The Roles:</strong></p><ul><li><strong>The Curator:</strong> Who manages Heidi&#39;s art and secrets.</li><li><strong>Alfred Alsberg:</strong> The former owner whose store Horten takes over.</li><li><strong>The Political Secretary:</strong> Who organizes the &quot;donations.&quot; <strong>The Performance:</strong> Masucci is the chameleon of the film. Through his multiple roles, he embodies the different faces of power and its victims, always with a touch of dark humor.</li></ul><hr><p><em>This cast ensures that &quot;The Horten Mystery&quot; is not just a documentary, but a high-carat cinematic event.</em></p>',11)])])}const g=t(s,[["render",i]]);export{d as __pageData,g as default};
